BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SELECT no_plan();
INSERT INTO auth.users(instance_id,id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) VALUES
('00000000-0000-0000-0000-000000000000','fd300000-0000-4000-8000-000000000001','authenticated','authenticated','upload-field@example.test','',now(),'{"provider":"email"}','{}',now(),now()),
('00000000-0000-0000-0000-000000000000','fd300000-0000-4000-8000-000000000002','authenticated','authenticated','upload-viewer@example.test','',now(),'{"provider":"email"}','{}',now(),now()),
('00000000-0000-0000-0000-000000000000','fd300000-0000-4000-8000-000000000003','authenticated','authenticated','upload-editor@example.test','',now(),'{"provider":"email"}','{}',now(),now());
INSERT INTO public.organizations(id,name,type,country) VALUES('fd301000-0000-4000-8000-000000000001','Synthetic upload org','test','Denmark'),('fd301000-0000-4000-8000-000000000002','Foreign upload org','test','Denmark');
INSERT INTO public.projects(id,organization_id,name) VALUES('fd302000-0000-4000-8000-000000000001','fd301000-0000-4000-8000-000000000001','Synthetic upload project'),('fd302000-0000-4000-8000-000000000002','fd301000-0000-4000-8000-000000000002','Foreign upload project');
INSERT INTO public.organization_memberships(organization_id,user_id,role) SELECT 'fd301000-0000-4000-8000-000000000001',id,'viewer' FROM auth.users WHERE id IN('fd300000-0000-4000-8000-000000000001','fd300000-0000-4000-8000-000000000002','fd300000-0000-4000-8000-000000000003');
INSERT INTO public.project_members(project_id,user_id,role) VALUES('fd302000-0000-4000-8000-000000000001','fd300000-0000-4000-8000-000000000001','field'),('fd302000-0000-4000-8000-000000000001','fd300000-0000-4000-8000-000000000002','viewer'),('fd302000-0000-4000-8000-000000000001','fd300000-0000-4000-8000-000000000003','editor');
INSERT INTO storage.buckets(id,name,public) VALUES('project-media','project-media',false) ON CONFLICT(id) DO NOTHING;
CREATE FUNCTION pg_temp.payload() RETURNS jsonb LANGUAGE sql AS $$ SELECT '{"title":"Synthetic capture","description":null,"category":"field_photo","tags":[],"originalName":"photo.jpg","sha256":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","sizeBytes":8,"mimeType":"image/jpeg","capturedAt":null,"capture":{"schema":"freyra.field-photo/v1","originalPosition":null,"initialPosition":{"lat":55,"lng":10},"correctionReason":"Synthetic manual point"}}'::jsonb $$;
CREATE FUNCTION pg_temp.begin_upload(p jsonb DEFAULT pg_temp.payload()) RETURNS uuid LANGUAGE sql AS $$ SELECT id FROM public.begin_field_photo_upload('fd302000-0000-4000-8000-000000000001','fd304000-0000-4000-8000-000000000001',p) $$;
CREATE FUNCTION pg_temp.finish_upload() RETURNS uuid LANGUAGE sql AS $$ SELECT id FROM public.finalize_field_photo_upload('fd302000-0000-4000-8000-000000000001','fd304000-0000-4000-8000-000000000001') $$;
CREATE FUNCTION pg_temp.prepare() RETURNS jsonb LANGUAGE sql AS $$ SELECT public.prepare_field_photo_verification('fd302000-0000-4000-8000-000000000001','fd304000-0000-4000-8000-000000000001','fd300000-0000-4000-8000-000000000001') $$;
CREATE FUNCTION pg_temp.complete(h text DEFAULT repeat('a',64), l uuid DEFAULT NULL) RETURNS text LANGUAGE sql AS $$ SELECT status FROM public.complete_field_photo_verification('fd302000-0000-4000-8000-000000000001','fd304000-0000-4000-8000-000000000001','fd300000-0000-4000-8000-000000000001',coalesce(l,(SELECT lease_id FROM public.field_photo_processing_jobs WHERE upload_id='fd304000-0000-4000-8000-000000000001')),h,8) $$;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','fd300000-0000-4000-8000-000000000002',true);
SELECT throws_ok($$SELECT pg_temp.begin_upload()$$,'42501',NULL,'viewer cannot start an upload');
SELECT set_config('request.jwt.claim.sub','fd300000-0000-4000-8000-000000000001',true);
SELECT throws_ok($$SELECT * FROM public.begin_field_photo_upload('fd302000-0000-4000-8000-000000000002',gen_random_uuid(),pg_temp.payload())$$,'42501',NULL,'project ids cannot cross the organization boundary');
SELECT lives_ok($$SELECT pg_temp.begin_upload()$$,'field employee can reserve an upload');
SELECT is(pg_temp.begin_upload(),'fd304000-0000-4000-8000-000000000001'::uuid,'lost intent response retries return the same identity');
SELECT throws_ok($$SELECT pg_temp.begin_upload(pg_temp.payload()||'{"title":"Changed capture"}')$$,'22023',NULL,'reused identity cannot change the capture');
SELECT throws_ok($$SELECT pg_temp.begin_upload(pg_temp.payload()||'{"verified":true}')$$,'22023',NULL,'client cannot submit a server verification status');
SELECT throws_ok($$SELECT pg_temp.begin_upload(pg_temp.payload()||'{"sizeBytes":52428801}')$$,'22023',NULL,'database enforces the file size limit');
SELECT throws_ok($$SELECT pg_temp.finish_upload()$$,'P0002',NULL,'missing object cannot become received');
SELECT is((SELECT count(*)::integer FROM public.field_photo_processing_jobs),0,'no job exists before receipt');
SELECT throws_ok($$INSERT INTO public.field_photo_receipts(upload_id) VALUES('fd304000-0000-4000-8000-000000000001')$$,'42501',NULL,'client cannot forge a server receipt');
SELECT set_config('request.jwt.claim.sub','fd300000-0000-4000-8000-000000000003',true);
SELECT throws_ok($$SELECT pg_temp.begin_upload()$$,'22023',NULL,'another editor cannot take over the request');
SELECT throws_ok($$INSERT INTO storage.objects(bucket_id,name,owner_id,metadata) VALUES('project-media','fd302000-0000-4000-8000-000000000001/field-uploads/fd304000-0000-4000-8000-000000000001/original','fd300000-0000-4000-8000-000000000003','{"size":8,"mimetype":"image/jpeg"}')$$,'42501',NULL,'even a project editor cannot occupy another persons reserved path');
SELECT set_config('request.jwt.claim.sub','fd300000-0000-4000-8000-000000000001',true);
SELECT lives_ok($$INSERT INTO storage.objects(id,bucket_id,name,owner_id,metadata) VALUES('fd303000-0000-4000-8000-000000000001','project-media','fd302000-0000-4000-8000-000000000001/field-uploads/fd304000-0000-4000-8000-000000000001/original','fd300000-0000-4000-8000-000000000001','{"size":8,"mimetype":"image/jpeg"}')$$,'field role can create the exact reserved object');
SELECT lives_ok($$UPDATE storage.objects SET name='renamed' WHERE id='fd303000-0000-4000-8000-000000000001'$$,'RLS filters replacement even before finalization');
SELECT is((SELECT name FROM storage.objects WHERE id='fd303000-0000-4000-8000-000000000001'),'fd302000-0000-4000-8000-000000000001/field-uploads/fd304000-0000-4000-8000-000000000001/original','reserved original path stays fixed');
SELECT lives_ok($$SELECT pg_temp.finish_upload()$$,'field employee finalizes the exact stored original');
SELECT is(pg_temp.finish_upload(),'fd304000-0000-4000-8000-000000000001'::uuid,'lost finalization response is idempotent');
SELECT is((SELECT count(*)::integer FROM public.project_media WHERE id='fd304000-0000-4000-8000-000000000001'),1,'one original media row is created');
SELECT is((SELECT url FROM public.project_media WHERE id='fd304000-0000-4000-8000-000000000001'),'','signed download URL is never persisted by finalization');
SELECT is((SELECT count(*)::integer FROM public.field_photo_processing_jobs),1,'one durable processing job is created');
SELECT is((SELECT count(*)::integer FROM public.field_photo_position_versions WHERE media_id='fd304000-0000-4000-8000-000000000001'),1,'initial correction is committed once');
SELECT ok((SELECT received_at IS NOT NULL AND object_id='fd303000-0000-4000-8000-000000000001' FROM public.field_photo_uploads),'receipt binds the real Storage object');
SELECT is((SELECT count(*)::integer FROM public.field_photo_receipts),0,'modtaget does not mean server verified');
SELECT throws_ok($$SELECT pg_temp.prepare()$$,'42501',NULL,'browser cannot invoke privileged processing RPC');
SELECT set_config('request.jwt.claim.sub','fd300000-0000-4000-8000-000000000003',true);
SELECT throws_ok($$UPDATE public.project_media SET is_report_ready=true WHERE id='fd304000-0000-4000-8000-000000000001'$$,'23514',NULL,'unverified upload cannot become report ready');
RESET ROLE;
SET LOCAL ROLE service_role;
SELECT lives_ok($$SELECT pg_temp.prepare()$$,'server acquires a processing lease');
SELECT throws_ok($$SELECT pg_temp.prepare()$$,'55P03',NULL,'second worker cannot process an active lease');
SELECT throws_ok($$SELECT pg_temp.complete(repeat('a',64),gen_random_uuid())$$,'40001',NULL,'another lease cannot commit a result');
SELECT lives_ok($$SELECT public.release_field_photo_verification('fd304000-0000-4000-8000-000000000001',(SELECT lease_id FROM public.field_photo_processing_jobs),'download_failed')$$,'interrupted download releases only its own lease');
SELECT lives_ok($$SELECT pg_temp.prepare()$$,'durable failed job can be retried');
SELECT is((SELECT attempts FROM public.field_photo_processing_jobs),2,'retry count is recorded');
RESET ROLE;
UPDATE storage.objects SET version='synthetic-changed-version' WHERE id='fd303000-0000-4000-8000-000000000001';
SET LOCAL ROLE service_role;
SELECT throws_ok($$SELECT pg_temp.complete()$$,'23514',NULL,'object changed during download cannot receive a receipt');
RESET ROLE;
UPDATE storage.objects SET version=(SELECT object_version FROM public.field_photo_uploads) WHERE id='fd303000-0000-4000-8000-000000000001';
DELETE FROM public.organization_memberships WHERE user_id='fd300000-0000-4000-8000-000000000001';
SET LOCAL ROLE service_role;
SELECT throws_ok($$SELECT pg_temp.complete()$$,'42501',NULL,'membership revocation before commit prevents verification');
RESET ROLE;
INSERT INTO public.organization_memberships(organization_id,user_id,role) VALUES('fd301000-0000-4000-8000-000000000001','fd300000-0000-4000-8000-000000000001','viewer');
SET LOCAL ROLE service_role;
SELECT is(pg_temp.complete(),'verified','server checksum matches the declared original');
SELECT is(pg_temp.complete(),'verified','lost verification response returns the existing receipt');
SELECT throws_ok($$SELECT pg_temp.complete(repeat('b',64))$$,'23514',NULL,'terminal receipt cannot be replaced by another checksum');
RESET ROLE;
SELECT throws_ok($$UPDATE public.field_photo_receipts SET sha256=repeat('b',64)$$,'23514',NULL,'receipt remains immutable even through an owner connection');
SELECT throws_ok($$DELETE FROM public.field_photo_receipts$$,'23514',NULL,'receipt cannot be removed');
SELECT throws_ok($$UPDATE public.field_photo_uploads SET payload='{}'$$,'23514',NULL,'original upload intent cannot be rewritten');
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','fd300000-0000-4000-8000-000000000003',true);
SELECT lives_ok($$UPDATE public.project_media SET is_report_ready=true WHERE id='fd304000-0000-4000-8000-000000000001'$$,'editor can mark a byte-verified original for reports');
SELECT set_config('request.jwt.claim.sub','fd300000-0000-4000-8000-000000000002',true);
SELECT is((SELECT count(*)::integer FROM public.field_photo_receipts),1,'project reader can inspect the server receipt');
RESET ROLE;
DELETE FROM public.organization_memberships WHERE user_id='fd300000-0000-4000-8000-000000000002';
SET LOCAL ROLE authenticated;
SELECT is((SELECT count(*)::integer FROM public.field_photo_receipts),0,'revoked reader cannot inspect receipts');
SELECT set_config('request.jwt.claim.sub','fd300000-0000-4000-8000-000000000001',true);
SELECT lives_ok($$SELECT * FROM public.begin_field_photo_upload('fd302000-0000-4000-8000-000000000001','fd304000-0000-4000-8000-000000000002',pg_temp.payload())$$,'second independent capture gets its own identity');
SELECT lives_ok($$INSERT INTO storage.objects(id,bucket_id,name,owner_id,metadata) VALUES('fd303000-0000-4000-8000-000000000002','project-media','fd302000-0000-4000-8000-000000000001/field-uploads/fd304000-0000-4000-8000-000000000002/original','fd300000-0000-4000-8000-000000000001','{"size":8,"mimetype":"image/jpeg"}')$$,'second object is uploaded unchanged');
SELECT lives_ok($$SELECT * FROM public.finalize_field_photo_upload('fd302000-0000-4000-8000-000000000001','fd304000-0000-4000-8000-000000000002')$$,'second received original creates another job');
RESET ROLE;
SET LOCAL ROLE service_role;
SELECT lives_ok($$SELECT public.prepare_field_photo_verification('fd302000-0000-4000-8000-000000000001','fd304000-0000-4000-8000-000000000002','fd300000-0000-4000-8000-000000000001')$$,'server leases second job');
UPDATE public.field_photo_processing_jobs SET lease_until=clock_timestamp()-interval '1 second' WHERE upload_id='fd304000-0000-4000-8000-000000000002';
SELECT lives_ok($$SELECT public.prepare_field_photo_verification('fd302000-0000-4000-8000-000000000001','fd304000-0000-4000-8000-000000000002','fd300000-0000-4000-8000-000000000001')$$,'crashed worker lease expires and permits recovery');
SELECT is((SELECT status FROM public.complete_field_photo_verification('fd302000-0000-4000-8000-000000000001','fd304000-0000-4000-8000-000000000002','fd300000-0000-4000-8000-000000000001',(SELECT lease_id FROM public.field_photo_processing_jobs WHERE upload_id='fd304000-0000-4000-8000-000000000002'),repeat('b',64),8)),'hash_mismatch','server-computed different bytes are retained as a mismatch');
RESET ROLE;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','fd300000-0000-4000-8000-000000000003',true);
SELECT throws_ok($$UPDATE public.project_media SET is_report_ready=true WHERE id='fd304000-0000-4000-8000-000000000002'$$,'23514',NULL,'checksum mismatch cannot be marked report ready');
RESET ROLE;
SELECT * FROM finish();
ROLLBACK;
